import { Readable } from 'node:stream';
async function main(): Promise<void> {
  const r2: any = new Readable({ read() {} });
  setTimeout(() => { console.log('t0'); r2.push('x'); console.log('t1'); r2.push('y'); console.log('t2'); r2.push(null); console.log('t3'); }, 5);
  for await (const c of r2) console.log(String(c));
}
